def _security() -> None:
    for table in TABLES:
        op.execute(f"""
            ALTER TABLE {table} ENABLE ROW LEVEL SECURITY;
            CREATE POLICY tenant_isolation ON {table}
              USING (organisation_id = app_current_org())
              WITH CHECK (organisation_id = app_current_org());
        """)
    # History is append-only for the application role.
    op.execute(
        "REVOKE UPDATE, DELETE, TRUNCATE ON insight_events, incident_events, ai_generations FROM operon_app"
    )
    # The escalation sweep runs for every organisation before any tenant context exists: it may
    # learn only which incidents are overdue, then sets each organisation's context to act.
    op.execute("""
        CREATE FUNCTION operon_incidents_due_for_escalation(p_now timestamptz, p_limit int)
        RETURNS TABLE (id uuid, organisation_id uuid)
        LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS
        $$ SELECT i.id, i.organisation_id FROM incidents i
           WHERE i.status = 'open' AND i.response_due_at <= p_now AND i.escalation_level < 3
           ORDER BY i.response_due_at LIMIT p_limit $$;
        REVOKE ALL ON FUNCTION operon_incidents_due_for_escalation(timestamptz, int) FROM PUBLIC;
        GRANT EXECUTE ON FUNCTION operon_incidents_due_for_escalation(timestamptz, int) TO operon_app;
    """)


def _permissions() -> None:
    table = sa.table(
        "permissions", sa.column("key", sa.String), sa.column("description", sa.String)
    )
    op.bulk_insert(table, [{"key": k, "description": d} for k, d in NEW_PERMISSIONS])
    for key, roles in GRANTS.items():
        op.execute(
            sa.text(
                "INSERT INTO role_permissions (organisation_id, role_id, permission_key) "
                "SELECT r.organisation_id, r.id, :key FROM roles r WHERE r.is_system AND r.key = ANY(:roles)"
            ).bindparams(key=key, roles=roles)
        )


